BEGIN;
ALTER TABLE public."MosqueRecord" DROP CONSTRAINT "MosqueRecord_kind_check";
ALTER TABLE public."MosqueRecord" ADD CONSTRAINT "MosqueRecord_kind_check" CHECK(kind IN ('dkm','jamaah','donasi','infaq','zakat','wakaf','keuangan','kegiatan','shalat','inventaris','petugas','penerima','umkm','broadcast','rekening'));
CREATE OR REPLACE FUNCTION mp_private.has_module(p_plan text, p_kind text)
 RETURNS boolean
 LANGUAGE sql
 IMMUTABLE
 SET search_path TO ''
AS $function$
 SELECT p_plan IN ('BASIC','PRO','ENTERPRISE') AND (
 p_kind IN ('dashboard','profil','rekening','dkm','donasi','infaq','zakat','wakaf','jamaah','setting') OR
 (p_plan IN ('PRO','ENTERPRISE') AND p_kind IN ('keuangan','kegiatan','penerima','shalat','laporan')) OR
 (p_plan='ENTERPRISE' AND p_kind IN ('inventaris','petugas','umkm','broadcast')));
$function$
;
CREATE OR REPLACE FUNCTION mp_private.validate_data(p_kind text, p_data jsonb)
 RETURNS void
 LANGUAGE plpgsql
 SET search_path TO ''
AS $function$
DECLARE defs jsonb:=$fields${"profil":[{"key":"name","label":"Nama Masjid","type":"text","optional":false},{"key":"vision","label":"Visi Masjid","type":"textarea","optional":true},{"key":"city","label":"Kota / Kabupaten","type":"text","optional":false},{"key":"address","label":"Alamat Masjid","type":"textarea","optional":false},{"key":"email","label":"Email Masjid","type":"email","optional":true},{"key":"website","label":"Alamat Website","type":"url","optional":true},{"key":"servicePhone","label":"Nomor Layanan Masjid","type":"tel","optional":true}],"dkm":[{"key":"name","label":"Nama Lengkap","type":"text","optional":false},{"key":"position","label":"Jabatan / Peran DKM","type":"select","options":["Ketua DKM","Sekretaris DKM","Bendahara DKM","Pembina DKM","Penasihat DKM","Muadzin","Imam Tetap","Imam Badal","Guru Kajian","Guru Tahsin & Tahfizh","Khotib Jumat","Publikasi & Broadcasting","Tim Kreatif","Pemuda Masjid","Marbot","Anggota"],"optional":false},{"key":"birthPlace","label":"Tempat Lahir","type":"text","optional":true},{"key":"birthDate","label":"Tanggal Lahir","type":"date","optional":true},{"key":"gender","label":"Jenis Kelamin","type":"select","options":["Laki-laki","Perempuan"],"optional":false},{"key":"address","label":"Alamat Lengkap","type":"textarea","optional":false},{"key":"phone","label":"Nomor WhatsApp","type":"tel","optional":false},{"key":"email","label":"Email","type":"email","optional":true},{"key":"education","label":"Pendidikan Terakhir","type":"text","optional":true},{"key":"occupation","label":"Pekerjaan","type":"text","optional":true},{"key":"expertise","label":"Keahlian / Bidang Pengabdian","type":"textarea","optional":true},{"key":"startDate","label":"Mulai Menjabat","type":"date","optional":false},{"key":"endDate","label":"Akhir Masa Jabatan","type":"date","optional":true},{"key":"active","label":"Pengurus aktif","type":"checkbox","optional":false},{"key":"note","label":"Keterangan","type":"textarea","optional":true}],"jamaah":[{"key":"name","label":"Nama Jamaah","type":"text","optional":false},{"key":"phone","label":"Nomor WhatsApp","type":"tel","optional":true},{"key":"email","label":"Email","type":"email","optional":true},{"key":"group","label":"Kelompok Jamaah","type":"select","options":["Umum","Remaja","Anak-anak","Lansia"],"optional":false},{"key":"active","label":"Jamaah aktif","type":"checkbox","optional":false},{"key":"note","label":"Keterangan","type":"textarea","optional":true}],"donasi":[{"key":"name","label":"Nama Donatur","type":"text","optional":true},{"key":"date","label":"Tanggal","type":"date","optional":false},{"key":"amount","label":"Nominal (Rp)","type":"number","optional":false},{"key":"method","label":"Metode Pembayaran","type":"select","options":["Transfer Bank","Tunai","QRIS"],"optional":false},{"key":"purpose","label":"Tujuan Donasi","type":"text","optional":false},{"key":"note","label":"Keterangan","type":"textarea","optional":true}],"infaq":[{"key":"receipt","label":"Jenis Penerimaan","type":"select","options":["Infaq","Shodaqoh"],"optional":false},{"key":"form","label":"Jenis Infaq/Shodaqoh","type":"select","options":["Barang","Makanan","Minuman","Uang","Lainnya"],"optional":false},{"key":"date","label":"Tanggal","type":"date","optional":false},{"key":"name","label":"Nama Pemberi","type":"text","optional":true},{"key":"amount","label":"Nominal Uang (Rp)","type":"number","optional":true},{"key":"item","label":"Nama Barang / Makanan / Minuman / Lainnya","type":"text","optional":true},{"key":"quantity","label":"Jumlah","type":"number","optional":true},{"key":"unit","label":"Satuan","type":"text","optional":true},{"key":"source","label":"Sumber Penerimaan","type":"select","options":["Kotak Masjid","Jumat","Transfer Bank","Tunai","QRIS","Takmir Masjid","Aplikasi","Lainnya"],"optional":false},{"key":"note","label":"Keterangan","type":"textarea","optional":true}],"zakat":[{"key":"name","label":"Nama Muzakki","type":"text","optional":false},{"key":"type","label":"Jenis Zakat","type":"select","options":["Zakat Fitrah","Zakat Maal"],"optional":false},{"key":"date","label":"Tanggal","type":"date","optional":false},{"key":"amount","label":"Nominal (Rp)","type":"number","optional":false},{"key":"distributed","label":"Sudah disalurkan","type":"checkbox","optional":false},{"key":"note","label":"Keterangan","type":"textarea","optional":true}],"wakaf":[{"key":"name","label":"Nama Wakif","type":"text","optional":false},{"key":"type","label":"Jenis Wakaf","type":"select","options":["Uang","Tanah","Bangunan","Peralatan","Lainnya"],"optional":false},{"key":"asset","label":"Nama Aset Wakaf","type":"text","optional":false},{"key":"date","label":"Tanggal","type":"date","optional":false},{"key":"amount","label":"Nominal Wakaf Uang (Rp)","type":"number","optional":true},{"key":"active","label":"Wakaf aktif","type":"checkbox","optional":false},{"key":"note","label":"Keterangan","type":"textarea","optional":true}],"keuangan":[{"key":"date","label":"Tanggal","type":"date","optional":false},{"key":"type","label":"Jenis Transaksi","type":"select","options":["Pemasukan","Pengeluaran"],"optional":false},{"key":"category","label":"Kategori Transaksi","type":"text","optional":false},{"key":"amount","label":"Nominal (Rp)","type":"number","optional":false},{"key":"account","label":"Akun Kas","type":"select","options":["Kas Tunai","Rekening Bank"],"optional":false},{"key":"note","label":"Keterangan","type":"textarea","optional":true}],"kegiatan":[{"key":"title","label":"Nama Kegiatan","type":"text","optional":false},{"key":"date","label":"Tanggal","type":"date","optional":false},{"key":"time","label":"Jam Mulai","type":"time","optional":false},{"key":"location","label":"Lokasi","type":"text","optional":false},{"key":"responsible","label":"Penanggung Jawab","type":"text","optional":false},{"key":"published","label":"Kegiatan dipublikasikan","type":"checkbox","optional":false},{"key":"note","label":"Keterangan","type":"textarea","optional":true}],"shalat":[{"key":"city","label":"Kota Jadwal Sholat","type":"select","options":["Jakarta","Bogor","Bandung","Semarang","Yogyakarta","Surabaya","Medan","Makassar","Denpasar","Balikpapan","Jayapura"],"optional":false},{"key":"confirmed","label":"Jadwal sudah diperiksa dengan jadwal resmi Masjid","type":"checkbox","optional":false},{"key":"note","label":"Keterangan","type":"textarea","optional":true}],"inventaris":[{"key":"name","label":"Nama Barang","type":"text","optional":false},{"key":"category","label":"Kategori Barang","type":"select","options":["Elektronik","Perlengkapan Ibadah","Furnitur","Kendaraan","Lainnya"],"optional":false},{"key":"quantity","label":"Jumlah","type":"number","optional":false},{"key":"unit","label":"Satuan","type":"text","optional":false},{"key":"condition","label":"Kondisi","type":"select","options":["Baik","Perlu Perawatan","Rusak"],"optional":false},{"key":"location","label":"Lokasi Penyimpanan","type":"text","optional":false}],"petugas":[{"key":"name","label":"Nama Donatur / Relawan","type":"text","optional":false},{"key":"role","label":"Peran","type":"select","options":["Donatur","Relawan","Donatur & Relawan"],"optional":false},{"key":"phone","label":"WhatsApp","type":"tel","optional":true},{"key":"email","label":"Email","type":"email","optional":true},{"key":"active","label":"Aktif","type":"checkbox","optional":false},{"key":"availability","label":"Kesediaan / Bidang Kontribusi","type":"textarea","optional":true}],"penerima":[{"key":"name","label":"Nama Penerima Manfaat","type":"text","optional":false},{"key":"category","label":"Golongan Penerima","type":"select","options":["Fakir","Miskin","Yatim","Janda","Lansia","Disabilitas","Korban Bencana","Santri/Penuntut Ilmu","Musafir"],"optional":false},{"key":"address","label":"Alamat / Domisili","type":"textarea","optional":false},{"key":"phone","label":"Nomor WhatsApp","type":"tel","optional":true},{"key":"guardian","label":"Nama Wali / Pendamping","type":"text","optional":true},{"key":"assistance","label":"Jenis Bantuan","type":"select","options":["Infaq","Shodaqoh","Donasi"],"optional":false},{"key":"needs","label":"Kebutuhan Bantuan","type":"textarea","optional":false},{"key":"active","label":"Penerima manfaat aktif","type":"checkbox","optional":false},{"key":"note","label":"Keterangan","type":"textarea","optional":true}],"umkm":[{"key":"name","label":"Nama Usaha","type":"text","optional":false},{"key":"owner","label":"Nama Pemilik","type":"text","optional":false},{"key":"category","label":"Kategori Usaha","type":"select","options":["Kuliner","Jasa","Perdagangan","Kerajinan","Lainnya"],"optional":false},{"key":"phone","label":"WhatsApp","type":"tel","optional":false},{"key":"address","label":"Alamat Usaha","type":"textarea","optional":false},{"key":"note","label":"Keterangan","type":"textarea","optional":true}],"broadcast":[{"key":"title","label":"Judul Pengumuman","type":"text","optional":false},{"key":"audience","label":"Penerima","type":"select","options":["Seluruh Jamaah","Pengurus","Donatur & Relawan"],"optional":false},{"key":"date","label":"Tanggal","type":"date","optional":false},{"key":"content","label":"Isi Pengumuman","type":"textarea","optional":false},{"key":"approved","label":"Isi pengumuman sudah diperiksa","type":"checkbox","optional":false}],"laporan":[{"key":"type","label":"Jenis Laporan","type":"select","options":["Keuangan","Donasi","Infaq & Shodaqoh","Zakat","Wakaf","Jamaah","Inventaris","Kegiatan","Penerima Manfaat"],"optional":false},{"key":"from","label":"Tanggal Awal","type":"date","optional":false},{"key":"to","label":"Tanggal Akhir","type":"date","optional":false}],"setting":[{"key":"name","label":"Nama Tampilan Masjid","type":"text","optional":false},{"key":"timezone","label":"Zona Waktu","type":"select","options":["Asia/Jakarta","Asia/Makassar","Asia/Jayapura"],"optional":false},{"key":"email","label":"Email Pemberitahuan","type":"email","optional":true},{"key":"website","label":"Alamat Website","type":"url","optional":true},{"key":"servicePhone","label":"Nomor Layanan Masjid","type":"tel","optional":true}],"rekening":[{"key":"type","label":"Jenis Rekening","type":"select","options":["Bank","E-wallet"],"optional":false},{"key":"provider","label":"Nama Bank / E-wallet","type":"text","optional":false},{"key":"number","label":"Nomor Rekening / E-wallet","type":"text","optional":false},{"key":"holder","label":"Atas Nama","type":"text","optional":false},{"key":"purpose","label":"Peruntukan","type":"text","optional":true}]}$fields$::jsonb; f jsonb; v jsonb; txt text; k text;
BEGIN
 IF jsonb_typeof(p_data)<>'object' OR octet_length(p_data::text)>16000 OR defs->p_kind IS NULL THEN RAISE EXCEPTION 'invalid_data'; END IF;
 FOR k IN SELECT jsonb_object_keys(p_data) LOOP
  IF NOT EXISTS(SELECT 1 FROM jsonb_array_elements(defs->p_kind) x WHERE x->>'key'=k) AND NOT(p_kind='dkm' AND k IN ('photoId','photoStatus')) THEN RAISE EXCEPTION 'unknown_field'; END IF;
 END LOOP;
 FOR f IN SELECT * FROM jsonb_array_elements(defs->p_kind) LOOP
  v:=p_data->(f->>'key');txt:=coalesce(v#>>'{}','');
  IF f->>'type'='checkbox' THEN IF v IS NOT NULL AND jsonb_typeof(v)<>'boolean' THEN RAISE EXCEPTION 'invalid_checkbox'; END IF; CONTINUE; END IF;
  IF v IS NOT NULL AND jsonb_typeof(v)<>'string' THEN RAISE EXCEPTION 'invalid_field'; END IF;
  IF (NOT coalesce((f->>'optional')::boolean,false) AND length(trim(txt))=0) OR length(txt)>(CASE WHEN f->>'type'='textarea' THEN 2000 ELSE 300 END) THEN RAISE EXCEPTION 'invalid_field'; END IF;
  IF txt<>'' AND f->>'type'='select' AND NOT (f->'options' ? txt) THEN RAISE EXCEPTION 'invalid_choice'; END IF;
  IF txt<>'' AND f->>'type'='number' THEN
   IF txt!~'^[0-9]+([.][0-9]+)?$' THEN RAISE EXCEPTION 'invalid_number'; END IF;
   IF txt::numeric>1000000000000 THEN RAISE EXCEPTION 'invalid_number'; END IF;
  END IF;
  IF txt<>'' AND f->>'type'='date' THEN
   IF txt!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' THEN RAISE EXCEPTION 'invalid_date'; END IF; PERFORM txt::date;
  END IF;
 END LOOP;
 IF p_kind='rekening' AND coalesce(p_data->>'number','')!~'^\+?[0-9][0-9 -]{3,38}[0-9]$' THEN RAISE EXCEPTION 'invalid_account_number'; END IF;
 IF p_kind='infaq' AND p_data->>'form'<>'Uang' THEN
  IF coalesce(p_data->>'item','')='' OR coalesce(p_data->>'unit','')='' OR coalesce(nullif(p_data->>'quantity',''),'0')::numeric<=0 THEN RAISE EXCEPTION 'invalid_non_cash'; END IF;
 END IF;
 IF p_kind='dkm' AND ((nullif(p_data->>'birthDate',''))::date>CURRENT_DATE OR (nullif(p_data->>'endDate',''))::date<(p_data->>'startDate')::date) THEN RAISE EXCEPTION 'invalid_dates'; END IF;
END $function$
;
CREATE OR REPLACE FUNCTION public.mp_public_workspace(p_mosque uuid)
 RETURNS jsonb
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
DECLARE assigned text; result jsonb;
BEGIN
 SELECT coalesce(s.plan,'BASIC'),jsonb_build_object('id',q.id,'name',q.name,'settings',(SELECT coalesce(jsonb_object_agg(k,v),'{}') FROM jsonb_each(jsonb_build_object('name',q.name)||coalesce(s.data,'{}')) x(k,v) WHERE k IN ('name','city','address','website','servicePhone','timezone','logoPhotoId','vision')))
 INTO assigned,result FROM public."Mosque" q LEFT JOIN public."MosqueSettings" s ON s."mosqueId"=q.id WHERE q.id=p_mosque AND q.status='ACTIVE' AND q."archivedAt" IS NULL;
 IF result IS NULL THEN RAISE EXCEPTION 'tenant_unavailable' USING ERRCODE='42501'; END IF;
 RETURN result||jsonb_build_object('plan',assigned,'canWrite',false,'records',coalesce((SELECT jsonb_agg(jsonb_build_object('id',r.id,'kind',r.kind,'createdAt',r."createdAt",'data',(SELECT coalesce(jsonb_object_agg(k,v),'{}') FROM jsonb_each(r.data) x(k,v) WHERE k=ANY(CASE WHEN r.kind='rekening' THEN ARRAY['type','provider','number','holder','purpose'] WHEN r.kind='dkm' THEN ARRAY['name','position','active'] WHEN r.kind='jamaah' THEN ARRAY['name','group','active'] WHEN r.kind='penerima' THEN ARRAY['name','category','assistance','active'] WHEN r.kind='petugas' THEN ARRAY['name','role','active'] ELSE ARRAY['name','title','type','date','time','amount','method','purpose','source','form','item','quantity','unit','distributed','active','asset','category','account','location','condition','owner','published','responsible','city','confirmed','audience','content','approved'] END))) ORDER BY r."createdAt" DESC) FROM public."MosqueRecord" r WHERE r."mosqueId"=p_mosque AND r."archivedAt" IS NULL AND mp_private.has_module(assigned,r.kind) AND r.kind NOT IN ('setting','profil','laporan')),'[]'::jsonb));
END $function$
;

-- A logo is read only through the signed Drive gateway and the active tenant guard.
CREATE OR REPLACE FUNCTION public.mp_set_mosque_logo(p_mosque uuid,p_photo text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path='' AS $$
DECLARE uid uuid:=mp_private.admin(p_mosque); saved jsonb;
BEGIN
 IF p_photo IS NULL OR p_photo!~'^[-_a-zA-Z0-9]{10,200}$' THEN RAISE EXCEPTION 'invalid_logo'; END IF;
 INSERT INTO public."MosqueSettings"("mosqueId",data) VALUES(p_mosque,jsonb_build_object('logoPhotoId',p_photo)) ON CONFLICT("mosqueId") DO UPDATE SET data=public."MosqueSettings".data||excluded.data,"updatedAt"=now() RETURNING data INTO saved;
 INSERT INTO public."AuditLog"("mosqueId","actorId",action,resource) VALUES(p_mosque,uid,'workspace.logo.update','MosqueSettings');
 RETURN jsonb_build_object('settings',saved);
END $$;
REVOKE ALL ON FUNCTION public.mp_set_mosque_logo(uuid,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.mp_set_mosque_logo(uuid,text) TO authenticated;
CREATE OR REPLACE FUNCTION public.mp_mosque_logo(p_mosque uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path='' AS $$
 SELECT s.data->>'logoPhotoId' FROM public."MosqueSettings" s JOIN public."Mosque" q ON q.id=s."mosqueId" WHERE q.id=p_mosque AND q.status='ACTIVE' AND q."archivedAt" IS NULL AND s.data->>'logoPhotoId'~'^[-_a-zA-Z0-9]{10,200}$';
$$;
REVOKE ALL ON FUNCTION public.mp_mosque_logo(uuid) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.mp_mosque_logo(uuid) TO anon,authenticated;

COMMIT;
